public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }
    if (sx == ex && sy == ey) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    java.util.function.Consumer<int[]> addEdge = (int[] p) -> {
        if (p.length != 4) return;
        int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            return;
        }
        String a = x1 + "," + y1;
        String b = x2 + "," + y2;
        adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    };
    for (int[] p : paths) {
        addEdge.accept(p);
    }

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    String startKey = sx + "," + sy;
    String endKey = ex + "," + ey;
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = adj.getOrDefault(cur, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

