public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }
    // Check remainder 0
    if (count[0] % 2 != 0) {
        return false;
    }
    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            continue; // already handled k even case
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

