    Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx = 0;
    Stack<Integer> stack = new Stack<>();
    stack.push(0);
    parent[0] = -2; // root marker
    while (!stack.isEmpty()) {
        int u = stack.pop();
        order[idx++] = u;
        for (int v : graph[u]) {
            if (parent[v] == -1) {
                parent[v] = u;
                stack.push(v);
            }
        }
    }
    int[] time = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        int t = 0;
