    if (n == 0) return 0;
    boolean[][] adj = new boolean[n][n];
    int max = 0;
    for (int v : A) if (v > max) max = v;
    int maxSum = max * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) isSquare[i * i] = true;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[A[i] + A[j]]) adj[i][j] = true;
        }
    }
    int size = 1 << n;
    int[][] dp = new int[size][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 1; mask < size; mask++) {
        for (int last = 0; last < n; last++) {
            int cur = dp[mask][last];
            if (cur == 0) continue;
            for (int next = 0; next < n; next++) {
